'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),cp=require('node:child_process');
const {out,known}=require('./collect-loomy-translate-skill-20261101.cjs');
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const files=JSON.parse(fs.readFileSync(path.join(out,'file-inventory.json'),'utf8')),seen=new Set();let verified=0;
for(const r of files){if(typeof r.file!=='string'||!/^[a-f0-9]{64}$/.test(r.sha256)||!Number.isSafeInteger(r.bytes)||r.bytes<0||!['git','release'].includes(r.storage))throw Error('Invalid artifact metadata');const p=path.resolve(out,r.file);if(!p.startsWith(out+path.sep))throw Error('Unsafe path');if(r.storage==='release'&&(r.asset!==path.basename(r.file)||r.asset!==path.basename(r.asset)||r.release!=='iflytek-loomy-skills-2026-11-01'))throw Error('Invalid release asset pointer');if(seen.has(r.sha256))throw Error('Duplicate published artifact');seen.add(r.sha256);if(known.get(r.sha256)?.inventory)throw Error('Already indexed in a prior collection '+r.file);
 if(!fs.existsSync(p)&&r.storage==='release'&&process.argv.includes('--restore')){fs.mkdirSync(path.dirname(p),{recursive:true});const result=cp.spawnSync('gh',['release','download',r.release,'--repo','covaciugnm/iFLYTEK','--pattern',r.asset,'--dir',path.dirname(p)],{stdio:'inherit',windowsHide:true});if(result.status!==0)throw Error('Download failed');}
 const b=fs.readFileSync(p);if(b.length!==r.bytes||sha(b)!==r.sha256)throw Error('Integrity mismatch '+r.file);if(r.file.endsWith('.pdf')&&b.subarray(0,5).toString()!=='%PDF-')throw Error('Not a PDF');verified++;
}
const archives=JSON.parse(fs.readFileSync(path.join(out,'archive-entries.json'),'utf8'));for(const f of files.filter(r=>/\.(zip|xapk)$/.test(r.file))){const a=archives.find(x=>x.file===f.file);if(!a||a.sha256!==f.sha256||a.items.length!==a.entries)throw Error('Missing ZIP validation '+f.file);if(f.file.startsWith('skills/')&&!a.items.some(x=>/(^|\/)SKILL\.md$/i.test(x.name)))throw Error('Skill package missing SKILL.md '+f.file);}
let remoteAssets=0;if(process.argv.includes('--remote')){const release=JSON.parse(cp.execFileSync('gh',['release','view','iflytek-loomy-skills-2026-11-01','--repo','covaciugnm/iFLYTEK','--json','isDraft,assets'],{encoding:'utf8',windowsHide:true}));if(release.isDraft)throw Error('Release is a draft');const expected=files.filter(r=>r.storage==='release');if(release.assets.length!==expected.length)throw Error('Remote asset count');for(const f of expected){const a=release.assets.find(a=>a.name===f.asset);if(!a||a.size!==f.bytes||a.digest!=='sha256:'+f.sha256)throw Error('Remote asset mismatch '+f.file);remoteAssets++;}}
